package org.sleepwell.app;

import android.app.*;
import android.os.*;
import android.widget.*;
import android.text.InputType;
import org.json.JSONObject;

/** One explicitly configured Home Assistant lamp; no discovery or requests merely on opening. */
public final class SmartLightActivity extends Activity {
    private final Handler main=new Handler(Looper.getMainLooper());private SmartLightConfig draft;private boolean busy;private String message="";private EditText endpoint,token,entity;private Switch enabled,restore;private long generation;
    @Override public void onCreate(Bundle state){super.onCreate(state);if(getIntent().getBooleanExtra("visualReview",false))getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(state!=null&&state.containsKey("draft"))try{draft=decode(new AutomationSecrets().open(state.getString("draft")));}catch(Exception ignored){}if(draft!=null)render();else load();}
    private void load(){busy=true;LinearLayout body=Design.page(this,false,null,n->{});Design.header(body,"Bedroom light",this::finish);Design.text(body,"Loading saved light…",14,400,Design.MUTED);long ticket=++generation;SmartLightAlarm.worker.execute(()->{SmartLightConfig config;String issue="";try{config=SmartLightSettings.load(this);}catch(Exception e){config=SmartLightConfig.empty();issue="Saved connection unavailable. Disconnect to enter it again.";}SmartLightConfig value=config;String error=issue;main.post(()->{if(isDestroyed()||ticket!=generation)return;busy=false;draft=value;message=error;render();});});}
    private void render(){if(draft==null)return;LinearLayout body=Design.page(this,false,null,n->{});Design.header(body,"Bedroom light",this::finish);Design.item(body,"bulb","Direct Philips Hue bridge","Pair one light over your private LAN",()->startActivity(RecordUi.intent(this,HueBridgeActivity.class)));Design.line(body);Design.text(body,"Home Assistant",19,600,Design.INK);if(HueBridgeSettings.enabled(this))Design.text(body,"Direct Hue is enabled. Turn it off before enabling Home Assistant.",13,500,Design.BROWN);Design.text(body,"Fade in one dimmable lamp when a real alarm starts.",13,400,Design.MUTED);Design.space(body,8);android.content.SharedPreferences savedStatus=SmartLightSettings.factory.preferences(this);Design.text(body,savedStatus.getString("status","Not configured"),13,500,Design.BROWN);String savedError=savedStatus.getString("error","");if(!savedError.isEmpty())Design.text(body,savedError,12,400,Design.MUTED);endpoint=field(body,"Server HTTPS address",draft.endpoint,false);token=field(body,"Long-lived access token",draft.token,true);entity=field(body,"Light entity",draft.entity,false);Design.space(body,8);PlanActivity.detail(body,"sun","Sunrise duration",null,draft.minutes+" min",()->{read();String[] minutes=new String[30];for(int n=0;n<minutes.length;n++)minutes[n]=(n+1)+" min";SleepPicker.choices(this,"Lamp sunrise duration",minutes,draft.minutes-1,n->{draft=copy(n+1,draft.maximum);render();});});PlanActivity.detail(body,"bulb","Maximum intensity",null,draft.maximum+"%",()->{read();String[] values=new String[100];for(int n=0;n<values.length;n++)values[n]=(n+1)+"%";SleepPicker.choices(this,"Maximum lamp intensity",values,draft.maximum-1,n->{draft=copy(draft.minutes,n+1);render();});});enabled=Design.toggle(body,"Use with all real alarms","Off until you enable and save.",draft.enabled,on->{});restore=Design.toggle(body,"Restore after alarm stops","Restore the earlier on/off and brightness when still owned.",draft.restore,on->{});Design.space(body,8);Design.text(body,"Requires your Home Assistant server and a dimmable light. Phone sound, sunrise and flashlight work independently.",12,400,Design.MUTED);if(!message.isEmpty()){Design.space(body,8);Design.text(body,message,13,500,Design.BROWN);}Design.button(body,"Check connection (read only)",false,this::check).setEnabled(!busy);Design.button(body,"Test lamp at up to 5%",false,this::test).setEnabled(!busy);Design.button(body,"Stop lamp test",false,SmartLightTest::stop);if(draft.revision>0||!SmartLightSettings.factory.preferences(this).getString("config","").isEmpty())Design.button(body,"Disconnect lamp",false,this::disconnect);LinearLayout footer=RecordUi.footer(body);Design.button(footer,busy?"Please wait…":"Save bedroom light",true,this::save).setEnabled(!busy);if(busy)RecordUi.enabled(body,false);}
    private EditText field(LinearLayout body,String title,String value,boolean password){Design.space(body,10);Design.text(body,title,13,500,Design.INK);EditText input=new EditText(this);input.setSingleLine(true);input.setTextSize(14);input.setTypeface(Design.font(this,400));input.setTextColor(Design.INK);input.setMinHeight(Design.dp(this,48));input.setPadding(Design.dp(this,12),Design.dp(this,8),Design.dp(this,12),Design.dp(this,8));input.setBackground(Design.shape(this,Design.SOFT,12));input.setContentDescription(title);input.setInputType(InputType.TYPE_CLASS_TEXT|(password?InputType.TYPE_TEXT_VARIATION_PASSWORD:InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS));input.setText(value);body.addView(input,new LinearLayout.LayoutParams(-1,-2));return input;}
    private SmartLightConfig copy(int minutes,int maximum){return new SmartLightConfig(draft.endpoint,draft.token,draft.entity,draft.enabled,minutes,maximum,draft.restore,draft.revision);}
    private void read(){if(endpoint!=null)draft=new SmartLightConfig(endpoint.getText().toString().trim(),token.getText().toString(),entity.getText().toString().trim(),enabled.isChecked(),draft.minutes,draft.maximum,restore.isChecked(),draft.revision);}
    private boolean valid(){read();try{draft.validate();if(draft.enabled&&HueBridgeSettings.enabled(this))throw new IllegalStateException("Turn off direct Hue before enabling Home Assistant.");return true;}catch(Exception e){message=e.getMessage();render();return false;}}
    private void save(){if(busy||!valid())return;SmartLightConfig value=draft;busy=true;message="";render();SmartLightTest.stop();SmartLightAlarm.stop();SmartLightAlarm.worker.execute(()->{SmartLightConfig saved=null;String issue="";try{saved=SmartLightSettings.save(this,value);}catch(Exception e){issue=e instanceof IllegalStateException?e.getMessage():"Connection could not be saved. Retry or disconnect.";}SmartLightConfig result=saved;String error=issue;main.post(()->{if(isDestroyed())return;busy=false;if(result!=null){draft=result;message=result.enabled?"Saved for the next real alarm.":"Saved. Bedroom light is off.";}else message=error;render();});});}
    private void check(){if(busy||!valid())return;SmartLightConfig value=draft;busy=true;message="Checking saved address…";render();SmartLightAlarm.worker.execute(()->{String result;try{SmartLightRun.State state=new HomeAssistantLight(value).read();result=state.dimmable?"Light reachable · brightness supported":"Light reachable but not dimmable; choose another entity.";}catch(Exception e){result="Light unavailable. Check server, token, entity and TLS certificate.";}String resultText=result;main.post(()->{if(isDestroyed())return;busy=false;message=resultText;render();});});}
    private void test(){if(busy||!valid())return;SmartLightConfig value=draft;ReportDialogs.show(new AlertDialog.Builder(this).setTitle("Test the lamp?").setMessage("This sends real commands at up to 5% brightness for 3 seconds, then attempts to restore its earlier state. A network or power failure may prevent restoration.").setNegativeButton("Cancel",null).setPositiveButton("Test lamp",(dialog,which)->{boolean started=SmartLightTest.start(value,status->main.post(()->{if(!isDestroyed()){message=status;render();}}));message=started?"Lamp test requested":"A real alarm owns the lamp. Try again after it ends.";render();}));}
    private void disconnect(){ReportDialogs.show(new AlertDialog.Builder(this).setTitle("Disconnect bedroom light?").setMessage("Saved credentials will be removed. The phone alarm stays independent.").setNegativeButton("Cancel",null).setPositiveButton("Disconnect",(d,w)->{SmartLightTest.stop();SmartLightAlarm.stop();SmartLightAlarm.worker.execute(()->{String result="";try{SmartLightSettings.disconnect(this);}catch(Exception e){result="Connection could not be removed. Retry.";}String error=result;main.post(()->{if(!isDestroyed()){message=error;load();}});});}));}
    private String encode()throws Exception{return new JSONObject().put("endpoint",draft.endpoint).put("token",draft.token).put("entity",draft.entity).put("enabled",draft.enabled).put("minutes",draft.minutes).put("maximum",draft.maximum).put("restore",draft.restore).put("revision",draft.revision).toString();}
    private SmartLightConfig decode(String text)throws Exception{JSONObject data=new JSONObject(text);return new SmartLightConfig(data.getString("endpoint"),data.getString("token"),data.getString("entity"),data.getBoolean("enabled"),data.getInt("minutes"),data.getInt("maximum"),data.getBoolean("restore"),data.getLong("revision"));}
    @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(draft!=null){read();try{state.putString("draft",new AutomationSecrets().seal(encode()));}catch(Exception ignored){}}}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    @Override protected void onDestroy(){generation++;SmartLightTest.stop();main.removeCallbacksAndMessages(null);super.onDestroy();}
}
